1587	  /** One "realnie → plan" value row with an optional realization bar.
1588	   *  ``elapsed`` (0..1) draws a tick at the elapsed fraction of the hour, so
1589	   *  a fill left of the tick reads "za planem", right of it "przed planem".
1590	   *
1591	   *  Reads **realized → plan**: what actually happened first, what was asked
1592	   *  for second. The realized number is the one being judged, so it leads and
1593	   *  carries the emphasis; the plan is the yardstick it is read against. */
1594	  private _pvRow(
1595	    label: string,
1596	    plan: number | null | undefined,
1597	    real: number | null | undefined,
1598	    opts: {
1599	      unit?: string;
1600	      digits?: number;
1601	      planOnly?: boolean;
1602	      elapsed?: number | null;
1603	      planSuffix?: string;
1604	      realSuffix?: string;
1605	    } = {}
1606	  ): TemplateResult | typeof nothing {
1607	    const p = plan ?? null;
1608	    const r = real ?? null;
1609	    const unit = opts.unit ?? "kWh";
1610	    const digits = opts.digits ?? 2;
1611	    if (
1612	      (p == null || Math.abs(p) < 0.005) &&
1613	      (r == null || Math.abs(r) < 0.005)
1614	    ) {
1615	      return nothing;
1616	    }
1617	    const showBar = !opts.planOnly && p != null && p > 0.005;
1618	    const ratio = showBar && r != null ? r / p : null;
1619	    return html`<div class="pv-row">
1620	      <span class="pv-label">${label}</span>
1621	      <span class="pv-vals">
1622	        ${opts.planOnly
1623	          ? html`<strong>${this._fmtNum(p, digits)}</strong> ${unit}${opts.planSuffix ?? ""}`
1624	          : html`<strong>${this._fmtNum(r, digits)}</strong>${opts.realSuffix ?? ""}
1625	              <span class="pv-arrow">→</span>
1626	              ${this._fmtNum(p, digits)}${opts.planSuffix ?? ""} ${unit}
1627	              ${ratio != null
1628	                ? html`<span class="pv-pct">${Math.round(ratio * 100)}%</span>`
1629	                : nothing}`}
1630	      </span>
1631	      ${showBar
1632	        ? html`<div class="pv-bar">
1633	            <div
1634	              class="pv-fill"
1635	              style=${`width:${Math.min(100, Math.max(0, (ratio ?? 0) * 100))}%`}
1636	            ></div>
1637	            ${opts.elapsed != null
1638	              ? html`<div
1639	                  class="pv-tick"
1640	                  style=${`left:${Math.min(100, opts.elapsed * 100)}%`}
1641	                ></div>`
1642	              : nothing}
1643	          </div>`
1644	        : nothing}
1645	    </div>`;
1646	  }
