1700	   *  hour asked for. The plan column is the hour's STARTING plan, so without
1701	   *  this a deliberate mid-hour revision is indistinguishable from the plan
1702	   *  having been wrong — the difference the user actually needs. */
1703	  private _revisionNote(hour: SeriesHour | null | undefined): TemplateResult | typeof nothing {
1704	    const revs = hour?.revisions ?? [];
