/**
 * Build ApexCharts options for the energy chart.
 *
      intersect: false,
      followCursor: false,
      // Custom HTML: show the total of the up-bar (supply) and down-bar
      // (consumption) plus the components that make up each sum — mirrors the
      // cost chart's tooltip style.
      custom: ({ dataPointIndex }: { dataPointIndex: number }) => {
        const h = hrs[dataPointIndex];
        if (!h) return "";
        const tt = dark
          ? { bg: "#1f2937", fg: "#f3f4f6", border: "#374151" }
          : { bg: "#ffffff", fg: "#1f2937", border: "#d1d5db" };
        const fmt = (v: number) => v.toFixed(2);
        const start = new Date(h.start);
        const date = start.toLocaleString("pl-PL", {
          weekday: "short",
          day: "2-digit",
          month: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
        });
        const modeMeta = h.inverter_mode ? INVERTER_MODE_META[h.inverter_mode] : null;
        const modeStr = modeMeta ? `  •  falownik: ${modeMeta.label}` : "";
        // Planned charger runtime for hours with EV charging (full power,
        // the automation stops the charger after this many minutes).
        // Charger runtime, both sides. The plan commits to a DURATION, so the
        // kWh alone cannot tell a short run from a slow one — this is the
        // comparison that says which. Measured to 5-minute buckets; an hour
        // that was measured and never ran reads "0 min", one with no
        // statistics at all is simply left out.
        const evMinBits = [
          h.ev_charge_minutes ? `plan ${h.ev_charge_minutes} min` : null,
          h.ev_minutes_real != null ? `realnie ${h.ev_minutes_real} min` : null,
        ].filter(Boolean);
        const evMinStr = evMinBits.length
          ? `  •  🚗 ładowanie: ${evMinBits.join(" · ")}`
          : "";

        // Trip away-windows covering this hour: the on-chart label is
        // truncated, so the tooltip carries the full event name + details
        // (event slot, departure/return incl. margins, distance, energy).
        const esc = (x: string) =>
          x.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c] ?? c);
        const fmtHM = (iso: string) => {
          const d = new Date(iso);
          return isNaN(d.getTime())
            ? "—"
            : d.toLocaleTimeString("pl-PL", { hour: "2-digit", minute: "2-digit" });
        };
        const hourTs = new Date(h.start).getTime();
        const tripRows = this._chartTrips()
          .filter((t) => {
            const a = new Date(t.depart).getTime();
            const b = new Date(t.return_end).getTime();
            return !isNaN(a) && !isNaN(b) && hourTs >= a && hourTs < b;
          })
          .map((t) => {
            const facts = [
              t.distance_km != null ? `${t.distance_km.toFixed(0)} km` : null,
              t.duration_min != null ? `dojazd ${Math.round(t.duration_min)} min` : null,
              t.energy_kwh != null ? `~${t.energy_kwh.toFixed(1)} kWh` : null,
            ]
              .filter(Boolean)
              .join(" · ");
            return (
              `<div style="font-weight:500;font-size:11px;opacity:0.85;margin-top:3px">🚗 ${esc(t.label)}</div>` +
              `<div style="font-weight:400;font-size:11px;opacity:0.75">` +
              `zdarzenie ${fmtHM(t.event_start)}–${fmtHM(t.event_end)} · wyjazd ${fmtHM(t.depart)} · powrót do ${fmtHM(t.return_end)}` +
              `</div>` +
              (facts
                ? `<div style="font-weight:400;font-size:11px;opacity:0.75">${facts}</div>`
                : "")
            );
          })
          .join("");

        // Split breakdown: realized vs forecast side by side, each with the
        // full colored per-position breakdown. Settled past hours carry both
        // (actual vs what was planned); future hours only forecast; the current
        // hour realized-so-far + the plan's forecast for the whole hour.
        const sides: { label: string; g: TipSide }[] = [];
        if (h.realized)
          sides.push({ label: h.partial ? "realne (do teraz)" : "realne", g: h.realized });
        if (h.forecast) {
          // Surface the vintage the forecast came from (date + hour) so the
          // forecast-lead view shows which plan each prognoza line reflects.
          const originStr = h.forecast_origin
            ? new Date(h.forecast_origin).toLocaleString("pl-PL", {
                day: "2-digit",
                month: "2-digit",
                hour: "2-digit",
                minute: "2-digit",
              })
            : null;
          const fcLabel =
            (h.partial ? "prognoza (godz.)" : "prognoza") +
            (originStr
              ? `<div style="font-weight:400;opacity:0.6;font-size:11px">z ${originStr}</div>`
              : "");
          sides.push({ label: fcLabel, g: h.forecast });
        }
        if (!sides.length) return "";

        if not current:
            return {}
        return {"reminders": current.reminders}


class EssChargeStartSensor(PowerPilotEntity, SensorEntity):
    """When the ongoing-or-next planned charge/passthrough block starts.

    The moment the ESS needs the grid: exposed as a timestamp so a user
    automation can connect the grid ahead of it (and keep it disconnected
    through pure battery-discharge stretches). While the current hour already
    charges or passes through, the value is that hour's start — a value in the
    past means "the grid should be connected right now".
    """

    _attr_translation_key = SENSOR_ESS_CHARGE_START
    _attr_device_class = SensorDeviceClass.TIMESTAMP
    _attr_icon = "mdi:transmission-tower-import"

    def __init__(self, coordinator, entry) -> None:
        super().__init__(coordinator, entry, SENSOR_ESS_CHARGE_START)

    @property
    def native_value(self):
        plan = self.plan
        if not plan:
            return None
        now = dt_util.now()
        for decision in plan.decisions:
            if decision.start + timedelta(hours=1) <= now:
                continue  # hour already over
            if decision.inverter_mode in (
                InverterMode.CHARGE,
                InverterMode.PASSTHROUGH,
            ):
                return decision.start
        return None


class EVChargeStartSensor(PowerPilotEntity, SensorEntity):
    """When the next planned EV charging hour starts (None if nothing planned).

    Exposed as a timestamp so an automation (or the UI) gets a live "in X"
    countdown without the value going stale between re-plans.
    """

    _attr_translation_key = SENSOR_EV_CHARGE_START
    _attr_device_class = SensorDeviceClass.TIMESTAMP
    _attr_icon = "mdi:clock-start"

    def __init__(self, coordinator, entry) -> None:
        super().__init__(coordinator, entry, SENSOR_EV_CHARGE_START)

    @property
    def native_value(self):
        start = self.coordinator.ev_control().get("charge_start")
        return dt_util.parse_datetime(start) if start else None


class EVChargeUntilSensor(PowerPilotEntity, SensorEntity):
    """When the charger should be switched back OFF (None if nothing planned).

    ``ev_charge_start`` alone is not enough to steer the charger: an hour the
    plan only wants partly charged needs an end as well, and for the hour
    already running the planned minutes are its *remainder*, so they cannot be
    counted from the top of the hour. This is that end, already clamped to the
    hour, so an automation can hold the charger on between the two timestamps
    without doing the arithmetic itself.
    """

    _attr_translation_key = SENSOR_EV_CHARGE_UNTIL
    _attr_device_class = SensorDeviceClass.TIMESTAMP
    _attr_icon = "mdi:clock-end"

    def __init__(self, coordinator, entry) -> None:
        super().__init__(coordinator, entry, SENSOR_EV_CHARGE_UNTIL)

    @property
    def native_value(self):
        until = self.coordinator.ev_control().get("charge_until")
        return dt_util.parse_datetime(until) if until else None


